Import ListNotations.
Open Scope Z_scope.
Unset Lia Cache. Unset Nia Cache. Unset Nra Cache.

Definition C9 : Z := 1000000000.

(* [comment removed for export] *)
Definition mstep (y : Z) : Z * Z :=
  let n := f128_to_u32 y in
  let c := f128_of_i32 1000000000 in
  let q := f128_of_u32 n in
  let d := f128_sub y q in
  (n, f128_mul c d).

(* [comment removed for export] *)
Fixpoint mloop (fuel : nat) (y : Z) : list Z * Z :=
  match fuel with
  | O => ([], y)
  | S f => let '(n, y') := mstep y in
           if f128_le y' 0 =? 0 then ([n], y') else let '(l, yf) := mloop f y' in (n :: l, yf)
  end.

