(* [comment removed for export] *)
Theorem prologue_finite d : 0 <= d < 2 ^ 64 -> 0 < d mod 2 ^ 63 < 2047 * 2 ^ 52 ->
  let N := dN d in let k := Z.log2 N in
  let ya := mk128 (abs_hi (f128_of_d d)) (lo64 (f128_of_d d)) in
  let F := mk128 (frexpl_hi (hi64 ya)) (lo64 ya) in
  let y1 := f128_mul F (f128_of_i32 2) in
  ya = qenc N (dE d) /\ fpclassifyl_mirror (lo64 ya) (hi64 ya) = 4 /\ 0 < frexpl_ee (hi64 ya) < 32767
  /\ F = qenc N (-1 - k) /\ frexpl_e (hi64 ya) = (dE d + k + 1) mod 2 ^ 64
  /\ y1 = qenc N (- k) /\ f128_le y1 0 = 1
  /\ f128_mul y1 (f128_of_d 0x41b0000000000000) = qenc (N * 2 ^ (52 - k)) (-24)
